      "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service IN ('invoice-agent', 'payment-service', 'order-service', 'workflow') ORDER BY service",
      "why": "Check disk usage for other services to identify if disk quota exhaustion is widespread or localized"
    }
  ],
  "hypotheses": [
