        {
          "action": "restart_service",
          "params": {"service": "worker"}
        },
        {
          "action": "requeue_orphaned_orders",
          "params": {}
        }
      ]
    },
    {
      "service": "sync-job",
      "kind": "resource_exhaustion",
      "mechanism": "Sync-job exhausted disk quota for ledger exports, causing sync failures",
      "supporting": ["E4", "E7", "E17"],
      "refuting": ["E34"],
      "explains": [],
